{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>{{BUSINESS_NAME}} — {{TAGLINE}}</title>
  <meta name="description" content="Intentional sound sessions and gatherings to help you breathe, rest, and return. Small groups, private offerings, and guided sessions in {{CITY}}, {{STATE}}." />
  <link rel="stylesheet" href="assets/css/styles.css" />
</head>
<body>
  <svg class="bg-pattern" aria-hidden="true"><use href="assets/img/pattern.svg#pattern" /></svg>

  <header class="site-header">
    <div class="wrap">
      <a class="brand" href="/">{{BUSINESS_NAME}}</a>
      <nav class="site-nav" aria-label="Primary">
        <a href="events.html">Gatherings</a>
        <a href="private-sessions.html">Sessions</a>
        <a href="pricing.html">Rates</a>
        <a href="about.html">Origins</a>
        <a href="faq.html">Questions</a>
        <a class="cta" href="book.html">Reserve</a>
        <a href="contact.html" class="muted">Connect</a>
      </nav>
    </div>
  </header>

  <main>
    <!-- HERO -->
    <section class="hero" id="hero">
      <div class="wrap">
        <h1 class="lead">An intentional pause—sound as a steady companion.</h1>
        <p class="sub">We design brief, held gatherings that refocus breathing, ease tension, and invite a clearer return to your day. Gentle instruments, guided presence.</p>
        <p class="meta">Upcoming in {{CITY}}, {{STATE}} • Questions? <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> • Call <a href="tel:{{PHONE}}">{{PHONE}}</a></p>
        <p class="actions">
          <a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          <a class="btn ghost" href="events.html">See Gatherings</a>
        </p>
      </div>
    </section>

    <!-- MYTH VS TRUTH -->
    <section class="myth-truth" id="myth_vs_truth">
      <div class="wrap">
        <h2>Myths and a quieter truth</h2>
        <div class="columns">
          <div class="card">
            <h3>Myth: It needs to be long</h3>
            <p>Truth: A focused, 30–45 minute container can re-tune the nervous system and sharpen rest without disrupting your day.</p>
          </div>
          <div class="card">
            <h3>Myth: You need experience</h3>
            <p>Truth: Everyone is welcome. We guide with clear cues and a slow, practical approach so new attendees feel held.</p>
          </div>
          <div class="card">
            <h3>Myth: It’s ceremonial or mystical</h3>
            <p>Truth: We use sound as a rehearsal for steadiness — practical, repeatable, and evidence-informed in spirit.</p>
          </div>
        </div>
      </div>
    </section>

    <!-- PILLARS + SESSION PLANNER -->
    <section class="pillars" id="pillars">
      <div class="wrap">
        <h2>Offerings reframed</h2>
        <div class="columns">
          <div class="pillar">
            <h3>Community Gatherings</h3>
            <p>Open-group sessions for short resets—group size kept intimate to preserve clarity.</p>
            <p class="muted">Duration: 40–60 minutes</p>
          </div>
          <div class="pillar">
            <h3>Bespoke Sessions</h3>
            <p>Private and corporate sessions tailored for a specific goal: sleep support, focus, or team re-centering.</p>
            <p class="muted">Custom length &amp; structure</p>
          </div>
          <div class="pillar">
            <h3>Hybrid Series</h3>
            <p>Short series designed to build a routine—mix of in-person and guided at-home practices.</p>
            <p class="muted">3–6 week cycles</p>
          </div>
        </div>

        <aside class="planner">
          <h3>Session Planner</h3>
          <p>Build a brief plan and export a plain-text summary you can save or share.</p>
          <form id="plannerForm">
            <label>Primary intention
              <select id="intent">
                <option>Ease into sleep</option>
                <option>Reset after stress</option>
                <option>Focus and clarity</option>
                <option>Soft group social reset</option>
              </select>
            </label>
            <label>Duration
              <select id="duration">
                <option>20 min</option>
                <option selected>40 min</option>
                <option>60 min</option>
              </select>
            </label>
            <label>Instruments
              <select id="instruments" multiple>
                <option>Gongs</option>
                <option>Crystal bowls</option>
                <option>Handpan</option>
                <option>Voice and toning</option>
                <option>Wind bells</option>
              </select>
            </label>
            <label>Experience level
              <select id="experience">
                <option>First time</option>
                <option>Some experience</option>
                <option>Regular</option>
              </select>
            </label>
            <div class="planner-controls">
              <button type="button" id="buildPlan" class="btn">Compose plan</button>
              <button type="button" id="copyPlan" class="btn ghost">Copy summary</button>
            </div>
          </form>
          <pre id="planOutput" class="output" aria-live="polite">Your plan summary will appear here.
</pre>
        </aside>
      </div>
    </section>

    <!-- CASE NOTES: testimonials + Upcoming Events with seat selector -->
    <section class="case-notes" id="case_notes">
      <div class="wrap">
        <h2>Case notes &amp; upcoming gatherings</h2>
        <div class="notes">
          <blockquote>"A clear, speedy way to settle the body before sleep. No drama, just precision." — L.</blockquote>
          <blockquote>"Held yet unpretentious—exactly the soft edge I needed." — M.</blockquote>
        </div>

        <div class="events">
          <div class="next-event">
            <h3>Next gathering</h3>
            <p class="date" id="nextEventDate">— loading —</p>
            <p class="desc">A short guided session focused on breath-based grounding and tonal support.</p>
            <p class="meta">Capacity: <span id="capacity">—</span></p>
          </div>

          <div class="calendar-list">
            <h4>Upcoming calendar</h4>
            <ul id="calendar">
              <!-- filled by JS -->
            </ul>
          </div>

          <div class="seating">
            <h4>Reserve your seat (demo)</h4>
            <p class="muted">Click a seat to toggle. This is a local demo — not a live booking.</p>
            <div id="seatMap" class="seat-map" role="grid" aria-label="seat map"></div>
            <div class="seat-controls">
              <button id="genPacking" class="btn">Generate packing list</button>
              <button id="copyPacking" class="btn ghost">Copy packing</button>
            </div>
            <pre id="packingOutput" class="output" aria-live="polite">Select seats to generate a simple packing list.
</pre>
          </div>
        </div>
      </div>
    </section>

    <!-- FAQ -->
    <section class="faq" id="faq">
      <div class="wrap">
        <h2>Questions & safety notes</h2>
        <div class="q">
          <h3>Who should not attend?</h3>
          <p>Contraindications: If you have uncontrolled epilepsy, recent head/ear injury, are pregnant and advised by a clinician to avoid vibrational therapies, or have other specific medical concerns, please consult your healthcare provider before attending and contact us at <a href="mailto:{{EMAIL}}">{{EMAIL}}</a>.</p>
        </div>
        <div class="q">
          <h3>How should I prepare?</h3>
          <p>Wear comfortable layers, bring a cushion or mat, and arrive a few minutes early to settle. We provide basic bolsters and blankets but recommend bringing items that make you comfortable.</p>
        </div>
        <div class="q">
          <h3>What if I need privacy or accessibility?</h3>
          <p>Contact us prior to your visit; we’ll make reasonable accommodations.</p>
        </div>
      </div>
    </section>

    <!-- FINAL CTA -->
    <section class="final-cta" id="cta">
      <div class="wrap">
        <h2>Ready to try a focused reset?</h2>
        <p>Book a spot at an upcoming gathering or request a private session tailored to your needs.</p>
        <p class="actions">
          <a class="btn primary" href="book.html">Reserve a Session</a>
          <a class="btn ghost" href="private-sessions.html">Request a Bespoke Offering</a>
        </p>
      </div>
    </section>
  </main>

  <footer class="site-footer">
    <div class="wrap">
      <p>&copy; <span id="year"></span> {{BUSINESS_NAME}} — small gatherings in {{CITY}}, {{STATE}} · <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> · <a href="tel:{{PHONE}}">{{PHONE}}</a></p>
      <nav class="small-nav">
        <a href="privacy.html">Privacy</a>
        <a href="terms.html">Terms</a>
        <a href="sitemap.xml">Sitemap</a>
      </nav>
    </div>
  </footer>

  <script src="assets/js/main.js"></script>
</body>
</html>"} 
