{"path":"assets/css/styles.css","content":"/* Minimal, calming styles — no external fonts. */
:root{
  --bg:#fbfbf9;--ink:#1b1b1b;--muted:#6b6b6b;--accent:#6b8a7f;--accent-2:#7c6b9f;--card:#ffffff;
  --radius:10px;--wrap:1100px;--gap:18px;
}
*{box-sizing:border-box}
html,body{height:100%}
body{font-family:system-ui,-apple-system,Segoe UI,Roboto,"Helvetica Neue",Arial;line-height:1.45;color:var(--ink);background:var(--bg);margin:0}
.wrap{max-width:var(--wrap);margin:0 auto;padding:48px 24px}
.bg-pattern{position:fixed;inset:0;width:100%;height:100%;opacity:0.06;pointer-events:none}
.site-header{background:transparent;padding:14px 0}
.site-header .wrap{display:flex;align-items:center;justify-content:space-between}
.brand{font-weight:700;color:var(--ink);text-decoration:none}
.site-nav a{margin-left:16px;color:var(--muted);text-decoration:none}
.site-nav a.cta{background:transparent;border:1px solid var(--muted);padding:8px 12px;border-radius:8px;color:var(--ink)}
.hero{padding:72px 0;background:linear-gradient(180deg,transparent,#fff0);}
.lead{font-size:clamp(24px,4vw,40px);margin:0 0 12px}
.sub{color:var(--muted);max-width:60ch}
.meta{color:var(--muted);font-size:14px}
.actions{margin-top:18px}
.btn{display:inline-block;padding:10px 16px;border-radius:10px;text-decoration:none;border:none;background:#eee;color:var(--ink);cursor:pointer}
.btn.primary{background:var(--accent);color:#fff}
.btn.ghost{background:transparent;border:1px solid #ddd}
.myth-truth{background:linear-gradient(180deg,#fff, #fbfbfb);padding:36px 0}
.columns{display:grid;grid-template-columns:repeat(3,1fr);gap:var(--gap);margin-top:18px}
.card{background:var(--card);padding:18px;border-radius:12px;box-shadow:0 6px 18px rgba(20,20,20,0.04)}
.pillars .columns{grid-template-columns:repeat(3,1fr)}
.pillar{padding:18px;background:var(--card);border-radius:12px}
.pillar .muted{color:var(--muted);font-size:13px}
.planner{margin-top:22px;padding:16px;border-radius:12px;background:linear-gradient(180deg,#fff,#f8fbf9)}
.planner form{display:grid;grid-template-columns:repeat(2,1fr);gap:10px}
.planner label{display:block;font-size:14px}
.planner select{width:100%;padding:8px;border-radius:8px;border:1px solid #e6e6e6}
.planner .planner-controls{grid-column:1/3;display:flex;gap:8px;padding-top:6px}
.output{background:#fafafa;border:1px solid #eee;padding:12px;border-radius:8px;white-space:pre-wrap}
.case-notes{padding:36px 0}
.notes blockquote{background:#fff;padding:12px;border-left:4px solid var(--accent-2);margin:0 0 12px}
.events{display:grid;grid-template-columns:1fr 1fr 1fr;gap:12px;margin-top:18px}
.next-event{background:var(--card);padding:14px;border-radius:10px}
.calendar-list{background:var(--card);padding:14px;border-radius:10px}
.seating{background:var(--card);padding:14px;border-radius:10px}
.seat-map{display:grid;grid-template-columns:repeat(8,1fr);gap:6px;margin-top:8px}
.seat{padding:8px;border-radius:6px;background:#f3f3f3;text-align:center;cursor:pointer}
.seat.taken{background:#d7d7d7;cursor:not-allowed;opacity:0.7}
.seat.selected{background:var(--accent);color:#fff}
.faq{padding:36px 0}
.faq .q{background:var(--card);padding:12px;border-radius:10px;margin-bottom:10px}
.final-cta{padding:48px 0;text-align:center}
.site-footer{border-top:1px solid #eee;padding:20px 0;margin-top:30px;background:transparent}
.site-footer p{margin:0;color:var(--muted)}
.small-nav a{margin-left:12px;color:var(--muted);text-decoration:none}
@media(max-width:880px){.columns,.events{grid-template-columns:1fr}.site-header .wrap{flex-direction:column;align-items:flex-start}.planner form{grid-template-columns:1fr}}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // Utilities
  function $(sel,root=document){return root.querySelector(sel)}
  function $all(sel,root=document){return Array.from(root.querySelectorAll(sel))}

  // Fill current year
  document.getElementById('year').textContent = new Date().getFullYear();

  // SESSION PLANNER
  var buildBtn = $('#buildPlan');
  var copyBtn = $('#copyPlan');
  var output = $('#planOutput');

  function composePlan(){
    var intent = $('#intent').value;
    var duration = $('#duration').value;
    var instruments = Array.from($('#instruments').selectedOptions).map(o=>o.value);
    var exp = $('#experience').value;
    var lines = [];
    lines.push('Session Plan — ' + new Date().toLocaleDateString());
    lines.push('Intention: ' + intent);
    lines.push('Duration: ' + duration);
    lines.push('Experience level: ' + exp);
    if(instruments.length) lines.push('Instruments: ' + instruments.join(', '));
    lines.push('Structure:');
    lines.push('- 0–5 min: arrival and orientation (gentle settling)');
    lines.push('- main: 60–80% of session: guided breath, steady tonal overlays');
    lines.push('- 5–10 min: transition back and short integration prompts');
    lines.push('\nNotes: Bring comfortable layers and a personal mat or cushion. This plan is a suggested structure; adapt during facilitation.');
    return lines.join('\n');
  }

  buildBtn.addEventListener('click',function(){
    output.textContent = composePlan();
  });

  copyBtn.addEventListener('click',function(){
    var text = output.textContent;
    if(!text) return;
    navigator.clipboard.writeText(text).then(function(){
      copyBtn.textContent = 'Copied';
      setTimeout(()=>copyBtn.textContent='Copy summary',1200);
    });
  });

  // UPCOMING EVENTS MODULE (demo data)
  var calendarEl = $('#calendar');
  var nextDateEl = $('#nextEventDate');
  var capacityEl = $('#capacity');

  var demoEvents = (function(){
    var base = new Date(); base.setDate(base.getDate()+3);
    var events=[];
    for(var i=0;i<6;i++){
      var d = new Date(base); d.setDate(base.getDate()+i*3);
      events.push({date:d.toISOString(),title:'Gathering — Ground & Tone',capacity:16});
    }
    return events;
  })();

  function renderEvents(){
    calendarEl.innerHTML = '';
    demoEvents.forEach((ev,i)=>{
      var li = document.createElement('li');
      var dd = new Date(ev.date);
      li.textContent = dd.toDateString() + ' — ' + ev.title;
      calendarEl.appendChild(li);
      if(i===0){
        nextDateEl.textContent = dd.toDateString();
        capacityEl.textContent = ev.capacity;
      }
    });
  }
  renderEvents();

  // SEAT SELECTOR + PACKING LIST
  var seatMap = $('#seatMap');
  var packingOut = $('#packingOutput');
  var genPacking = $('#genPacking');
  var copyPacking = $('#copyPacking');

  var seats = [];
  function initSeats(rows,cols){
    seatMap.innerHTML = '';
    seats = [];
    var total = rows*cols;
    for(var i=0;i<total;i++){
      var btn = document.createElement('button');
      btn.className = 'seat';
      btn.type = 'button';
      btn.textContent = i+1;
      // Randomly mark some seats as taken to simulate occupancy
      if(Math.random() < 0.2){ btn.classList.add('taken'); btn.disabled = true; }
      seatMap.appendChild(btn);
      seats.push({el:btn,selected:false,taken:btn.disabled,index:i+1});
    }
  }

  initSeats(2,8);

  seatMap.addEventListener('click',function(e){
    if(!e.target.classList.contains('seat')) return;
    if(e.target.classList.contains('taken')) return;
    e.target.classList.toggle('selected');
    var idx = parseInt(e.target.textContent,10);
    var record = seats.find(s=>s.index===idx);
    record.selected = e.target.classList.contains('selected');
    updatePackingPreview();
  });

  function updatePackingPreview(){
    var chosen = seats.filter(s=>s.selected).map(s=>s.index);
    if(chosen.length===0){
      packingOut.textContent = 'Select seats to generate a simple packing list.';
      return;
    }
    var lines = [];
    lines.push('Seats: ' + chosen.join(', '));
    lines.push('Suggested packing:');
    lines.push('- Comfortable mat or cushion');
    lines.push('- Light blanket (for warmth and grounding)');
    lines.push('- Water bottle');
    if(chosen.length>1) lines.push('- Small personal pillow for longer comfort');
    if(chosen.length>3) lines.push('- Earplugs for deeper focus (optional)');
    lines.push('\nArrival: plan to arrive 10 minutes early to settle. This seat selection is a local demo, not a confirmed booking.');
    packingOut.textContent = lines.join('\n');
  }

  genPacking.addEventListener('click',updatePackingPreview);

  copyPacking.addEventListener('click',function(){
    var txt = packingOut.textContent;
    if(!txt) return;
    navigator.clipboard.writeText(txt).then(function(){
      copyPacking.textContent = 'Copied';
      setTimeout(()=>copyPacking.textContent='Copy packing',1200);
    });
  });

  // small accessibility touch: focus outline for keyboard nav
  document.addEventListener('keydown',function(e){
    if(e.key==='Tab') document.body.classList.add('show-focus');
  });

})();"} 
